SHORTS = {'clip1-head': {'title': ['What goes through a shy', 'kid\'s head before "hi"'], 'dur': 57.186, 'segs': [('Five kids are playing ball in the park.', 0.12, 2.329, 1), ("Om is six. He's standing by the bench.", 2.751, 5.579, 2), ('He wants to say one word. "Hi."', 5.848, 8.576, 3), ("In Om's head, those ten steps feel like ten kilometers.", 9.296, 13.248, 5), ("Let's look at what goes through Om's head in those ten seconds.", 13.968, 17.009, 19), ('"Will they let me play?"', 17.499, 18.58, 20), ('"If I say something wrong, will they laugh?"', 19.019, 21.324, 21), ('"Could I be their friend?"', 21.819, 22.877, 22), ('And under all of these sits a question he can\'t put into words: "Am I good enough?"', 23.319, 28.526, 23), ('For an adult, saying hi takes two seconds.', 29.623, 32.499, 24), ("For a child, it's a risk.", 32.809, 34.642, 25), ("He's putting himself in front of other people, and whether they say yes or no is out of his hands.", 34.952, 40.118, 26), ('When a young child hears "no", they don\'t hear "the game is full right now."', 40.472, 44.504, 27), ('They hear "we don\'t want you."', 44.867, 46.678, 28), ("So the mind decides it's safer not to ask. If you never ask, nobody can turn you down.", 47.078, 52.414, 29), ('Om takes two steps forward, stops, and walks back to the bench.', 52.814, 56.936, 30)]}, 'clip2-liking': {'title': ["Kids think they're", 'less liked than they are'], 'dur': 50.181, 'segs': [('In 2018, Erica Boothby and her colleagues studied conversations between strangers.', 0.12, 5.43, 40), ('Two people chat for a few minutes. Then each one is asked, "How much did the other person like you?"', 5.904, 11.708, 41), ('Most people guessed too low. Their partners actually liked them more than they thought.', 12.249, 16.686, 42), ('Researchers call this the liking gap.', 17.156, 19.514, 43), ('In 2021, Wouter Wolf, working with Michael Tomasello, ran a similar study with children aged four to eleven.', 19.944, 27.046, 44), ("The four-year-olds didn't show the gap. They assumed the other kid liked them just as much as they liked the other kid.", 27.454, 32.933, 45), ('The gap appeared at around age five, which is the age when children start to care what others think of them.', 32.933, 38.817, 46), ('And it grew wider as the children got older.', 39.254, 41.631, 47), ('So when Om thinks, "They won\'t let me in," it\'s often not true.', 42.065, 46.211, 48), ("It's a guess, and the guess is usually stacked against him.", 46.502, 49.931, 49)]}, 'clip3-reject': {'title': ['How the fear of rejection', 'makes itself come true'], 'dur': 57.805, 'segs': [('Sometimes that guess makes itself come true.', 0.12, 2.745, 50), ('Columbia University psychologist Geraldine Downey called this rejection sensitivity:', 3.247, 8.511, 51), ('anxiously expecting rejection, and spotting it in the smallest signals.', 8.96, 13.204, 52), ('In 1998, her team studied children in fifth to seventh grade.', 13.569, 17.464, 53), ('Each child was asked to invite a classmate to join them for an interview.', 17.821, 21.341, 54), ("A little later, they were told the classmate didn't want to come. No reason was given.", 21.693, 26.065, 55), ('Children who expected rejection, and expected to feel angry about it, were more upset by this small, unclear "no".', 26.46, 33.718, 56), ('And according to their teachers, the kids high in rejection sensitivity had more trouble with peers a year later.', 34.033, 39.912, 57), ('It works like a loop.', 40.333, 41.421, 58), ('A child who thinks "they\'ll reject me" hangs back, or acts stiff and awkward.', 41.683, 46.662, 59), ("The other kids read that as distance, so they don't invite them.", 46.984, 50.021, 60), ('And the child concludes, "See? I knew it."', 50.322, 53.09, 61), ('Before anyone else turned them down, they had already turned themselves down.', 53.399, 57.555, 62)]}, 'clip4-parents': {'title': ['3 things to do for', 'a shy child'], 'dur': 57.493, 'segs': [('Parents can start three things today.', 0.12, 2.269, 78), ('One: drop the label.', 2.658, 4.494, 79), ('When a child keeps hearing "he\'s shy", it can become part of who they think they are.', 4.875, 9.467, 80), ('Try saying, "He likes to watch for a bit first." That\'s true, and it carries no blame.', 10.008, 15.319, 81), ('Two: teach "hi" in small steps.', 15.863, 18.84, 82), ('Role-play at home. You play the new kid, and your child introduces themselves.', 19.283, 23.597, 83), ('"Hi, I\'m Om. I like playing ball. Can I play too?"', 23.907, 27.22, 84), ("That's three sentences. Once they've said them ten times at home, saying them once at the park gets easier.", 27.65, 33.599, 85), ("And don't push them straight into a big group. Start with one child, then the group. A playdate at home with one friend is a good first step.", 34.023, 42.064, 86), ('Three: praise the attempt, not the outcome.', 42.615, 45.748, 87), ('If your child says hi and the other kids don\'t let them in, still say, "You went up and talked to them yourself. I loved that."', 46.135, 53.244, 88), ("That teaches them their worth doesn't depend on someone else's yes.", 53.648, 57.243, 89)]}, 'clip5-mirror': {'title': ['Why a friendly smile can', 'look like teasing'], 'dur': 34.61, 'segs': [('Think of it as a mirror.', 0.12, 1.406, 71), ('When a child looks at other kids, they see their own opinion of themselves reflected back.', 1.763, 6.365, 72), ('If the mirror is foggy, even a friendly smile can look like teasing.', 6.712, 10.524, 73), ("A young child can't clean that mirror alone. That job starts at home.", 10.959, 15.206, 74), ('Carl Rogers called it unconditional positive regard:', 15.627, 18.863, 75), ('a child feeling loved regardless of their grades, their performance, or how talkative they are.', 19.178, 24.135, 76), ("A child who feels that kind of love is more willing to go out and explore, because they know there's a safe place to come back to. Attachment researchers call this a secure base.", 24.471, 34.36, 77)]}}
